      "codigo_refatorado": "using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;

        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;

        [Range(1, 50)]
        public int cubesPerFrame = 1;

        public bool useUniqueMaterials = false;

        [Range(1, 512)]
        public int cpuScansPerFrame = 1;

        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;

        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private StringBuilder _reusableStringBuilder;
        private object[][] _preallocatedBlocks;
        private MaterialPropertyBlock _propertyBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            _reusableStringBuilder = new StringBuilder(gcConcatIterations * 4);
            _propertyBlock = new MaterialPropertyBlock();

            if (gcArrayAllocs > 0)
            {
                _preallocatedBlocks = new object[gcArrayAllocs][];
                for (int i = 0; i < gcArrayAllocs; i++)
                {
                    _preallocatedBlocks[i] = new object[10000];
                }
            }
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject(string.Concat("Empty_", i));
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                var col = quad.GetComponent<Collider>();
                if (col != null) Destroy(col);
                quad.name = string.Concat("Overdraw_", i);
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _reusableStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _reusableStringBuilder.Append(i);
                }
            }

            if (stressCpu)
            {
                // Evita alocações e varreduras O(N) custosas por frame
                int activeCount = transform.childCount;
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    activeCount += k;
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    // Usa MaterialPropertyBlock para não clonar materiais na memória
                    renderer.GetPropertyBlock(_propertyBlock);
                    _propertyBlock.SetColor(ColorPropertyId, new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value));
                    renderer.SetPropertyBlock(_propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "No C#, strings são imutáveis: toda vez que você faz 's += i.ToString()', o computador cria uma nova string inteira na memória e descarta a anterior. Fazer isso milhares de vezes por segundo gera montanhas de 'lixo' de memória (GC Alloc). Quando essa memória se enche, o Unity congela o jogo por vários milissegundos para limpá-la (o Garbage Collector), causando travamentos visíveis ('stutters'). Para evitar isso, reutilizamos buffers existentes como o StringBuilder, evitamos criar novos arrays dentro do Update e usamos MaterialPropertyBlock para mudar cores sem duplicar materiais na memória de vídeo."
    }
  ],
  "dicas_level_design": null
}

